+    private static byte[] serialize(List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(violation.replace("\n", "\\\n")).append("\n");
+        }
+        return builder.toString().getBytes(UTF_8);
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+        checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+        List<String> result = readLines(storeFolder.toPath().resolve(ruleDetailsFileName));
+        log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+        return result;
+    }
+
+    private List<String> readLines(Path file) {
+        String violationsText = readStoreFile(file);
+        if (isOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private static boolean isOnlyLineBreaks(String text) {
+        for (int i = 0; i < text.length(); i++) {
+            char character = text.charAt(i);
+            if (character != '\n' && character != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private String readStoreFile(Path file) {
+        try {
+            return ensureUnixLineBreaks(new String(toByteArray(file.toFile()), UTF_8));
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private enum Integrity {
+        IGNORE, REPAIR, FAIL
+    }
+
+    private static class FileNameConfiguration {
+        private final RuleViolationFileNameStrategy strategy;
+        private final boolean random;
+
+        FileNameConfiguration(RuleViolationFileNameStrategy strategy, boolean random) {
+            this.strategy = strategy;
+            this.random = random;
+        }
+    }
+
+    private static class Entry {
+        private final String description;
+        private final String recordedName;
+        private final Path namedPath;
+        private Path resolvedPath;
+        private String derivedName;
+        private boolean broken;
+        private boolean resolved;
+        private boolean shared;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+
+        Entry(String description, String recordedName, Path namedPath) {
+            this.description = description;
+            this.recordedName = recordedName;
+            this.namedPath = namedPath;
+        }
+    }
+
+    private static class IntegrityReport {
+        private final List<Entry> entries;
+        private final List<String> unownedFiles;
+
+        IntegrityReport(List<Entry> entries, List<String> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+        }
+
+        boolean hasProblems() {
+            if (!unownedFiles.isEmpty()) {
+                return true;
+            }
+            for (Entry entry : entries) {
+                if (entry.broken || entry.resolved || entry.shared || entry.misplaced || entry.colliding || entry.occupied) {
+                    return true;
+                }
+            }
+            return false;
+        }
+
+        String message() {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed");
+            appendEntries(result, "broken", entries, entry -> entry.broken);
+            appendEntries(result, "resolved", entries, entry -> entry.resolved);
+            appendEntries(result, "shared", entries, entry -> entry.shared);
+            appendEntries(result, "misplaced", entries, entry -> entry.misplaced);
+            appendEntries(result, "colliding", entries, entry -> entry.colliding);
+            appendEntries(result, "occupied", entries, entry -> entry.occupied);
+            if (!unownedFiles.isEmpty()) {
+                result.append("; unowned files: ").append(String.join(", ", unownedFiles));
+            }
+            return result.toString();
+        }
+
+        private void appendEntries(StringBuilder result, String condition, List<Entry> allEntries, EntryCondition predicate) {
+            List<Entry> matching = allEntries.stream().filter(predicate::matches)
+                    .sorted(Comparator.comparing(entry -> entry.description)).collect(toList());
+            if (!matching.isEmpty()) {
+                result.append("; ").append(condition).append(" entries: ");
+                result.append(matching.stream().map(entry -> entry.description + " -> " + entry.recordedName)
+                        .collect(java.util.stream.Collectors.joining(", ")));
+            }
+        }
+    }
+
+    @FunctionalInterface
+    private interface EntryCondition {
+        boolean matches(Entry entry);
+    }
+
+    /**
+     * The in-memory index and its filesystem are deliberately synchronized together. This is what prevents one store
+     * instance from inspecting a file while another instance is replacing it.
+     */
+    private class FileSyncedProperties {
+        private File folder;
+        private File indexFile;
+        private Path folderPath;
+        private Path indexPath;
+        private Properties loadedProperties;
+        private boolean initialized;
+
+        synchronized void initialize(File folder, File indexFile, boolean allowCreation, Integrity integrity,
+                FileNameConfiguration names) {
+            this.folder = folder;
+            this.indexFile = indexFile;
+            this.folderPath = folder.getAbsoluteFile().toPath().normalize();
+            this.indexPath = indexFile.getAbsoluteFile().toPath().normalize();
+
+            boolean indexExists = prepareFilesystem(allowCreation);
+            if (!initialized) {
+                loadedProperties = indexExists ? loadRulesFrom(indexFile) : new Properties();
+            }
+
+            if (integrity == Integrity.IGNORE) {
+                if (!indexExists) {
+                    writeProperties(loadedProperties, true);
+                }
+                initialized = true;
+                return;
+            }
+
+            IntegrityReport report = inspect(names);
+            if (integrity == Integrity.FAIL) {
+                if (report.hasProblems()) {
+                    throw new StoreInitializationFailedException(report.message());
+                }
+                if (!indexExists) {
+                    writeProperties(loadedProperties, true);
+                }
+                initialized = true;
+                return;
+            }
+
+            repair(report, indexExists);
+            initialized = true;
+        }
+
+        private boolean prepareFilesystem(boolean allowCreation) {
+            try {
+                if (!Files.exists(folderPath, LinkOption.NOFOLLOW_LINKS)) {
+                    if (!allowCreation) {
+                        throw new StoreInitializationFailedException(String.format(
+                                "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                                ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+                    }
+                    Files.createDirectories(folderPath);
+                }
+                if (!Files.isDirectory(folderPath, LinkOption.NOFOLLOW_LINKS)) {
+                    throw new StoreInitializationFailedException("Violation store path is not a directory: " + folder.getAbsolutePath());
+                }
+
+                boolean indexExists = Files.exists(indexPath, LinkOption.NOFOLLOW_LINKS);
+                if (indexExists && (!Files.isRegularFile(indexPath, LinkOption.NOFOLLOW_LINKS)
+                        || !folderPath.equals(indexPath.getParent()))) {
+                    throw new StoreInitializationFailedException(
+                            "Violation store index is not a regular file directly in the store folder: " + indexFile.getAbsolutePath());
+                }
+                if (!indexExists && !allowCreation) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                            ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+                }
+                return indexExists;
+            } catch (StoreInitializationFailedException e) {
+                throw e;
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+        }
+
+        private Properties loadRulesFrom(File file) {
+            Properties result = new Properties();
+            try (FileInputStream inputStream = new FileInputStream(file)) {
+                result.load(inputStream);
+            } catch (IOException e) {
+                throw new StoreInitializationFailedException(e);
+            }
+            return result;
+        }
+
+        synchronized boolean containsKey(String propertyName) {
+            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
+        }
+
+        synchronized String getProperty(String propertyName) {
+            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
+        }
+
+        private IntegrityReport inspect(FileNameConfiguration names) {
+            List<Entry> entries = new ArrayList<>();
+            for (String description : loadedProperties.stringPropertyNames()) {
+                String recordedName = loadedProperties.getProperty(description);
+                Entry entry = new Entry(description, recordedName, folderPath.resolve(recordedName == null ? "" : recordedName).normalize());
+                resolve(entry);
+                entry.derivedName = names.random ? recordedName : names.strategy.createRuleFileName(description);
+                if (entry.derivedName == null || entry.derivedName.length() == 0) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "RuleViolationFileNameStrategy produced no name for rule '%s'", description));
+                }
+                entry.misplaced = !entry.recordedName.equals(entry.derivedName);
+                entries.add(entry);
+            }
