+            markShared(entries);
+            markCollisionsAndOccupancy(entries);
+            return new IntegrityReport(entries, findUnownedFiles(entries));
+        }
+
+        private void resolve(Entry entry) {
+            try {
+                if (!Files.exists(entry.namedPath, LinkOption.NOFOLLOW_LINKS)) {
+                    entry.broken = true;
+                    return;
+                }
+                entry.resolvedPath = entry.namedPath.toRealPath();
+                boolean regular = Files.isRegularFile(entry.resolvedPath, LinkOption.NOFOLLOW_LINKS);
+                boolean direct = regular && folderPath.equals(entry.resolvedPath.getParent());
+                boolean index = entry.resolvedPath.equals(indexPath);
+                entry.broken = !direct || index;
+                if (!entry.broken) {
+                    entry.resolved = readLines(entry.resolvedPath).isEmpty();
+                }
+            } catch (IOException e) {
+                entry.broken = true;
+            }
+        }
+
+        private void markShared(List<Entry> entries) {
+            Map<String, List<Entry>> byName = new HashMap<>();
+            Map<String, List<Entry>> byResolvedPath = new HashMap<>();
+            for (Entry entry : entries) {
+                byName.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
+                if (entry.resolvedPath != null && Files.isRegularFile(entry.resolvedPath, LinkOption.NOFOLLOW_LINKS)) {
+                    byResolvedPath.computeIfAbsent(entry.resolvedPath.toString(), ignored -> new ArrayList<>()).add(entry);
+                }
+            }
+            markGroupsShared(byName);
+            markGroupsShared(byResolvedPath);
+        }
+
+        private void markGroupsShared(Map<String, List<Entry>> groups) {
+            for (List<Entry> group : groups.values()) {
+                if (group.size() > 1) {
+                    for (Entry entry : group) {
+                        entry.shared = true;
+                    }
+                }
+            }
+        }
+
+        private void markCollisionsAndOccupancy(List<Entry> entries) {
+            Map<String, List<Entry>> byDerivedName = new HashMap<>();
+            for (Entry entry : entries) {
+                byDerivedName.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+            }
+            for (List<Entry> group : byDerivedName.values()) {
+                if (group.size() > 1) {
+                    for (Entry entry : group) {
+                        entry.colliding = true;
+                    }
+                }
+            }
+
+            Set<String> recordedNames = new HashSet<>();
+            for (Entry entry : entries) {
+                recordedNames.add(entry.recordedName);
+            }
+            for (Entry entry : entries) {
+                if (!entry.misplaced) {
+                    continue;
+                }
+                Path derivedPath = folderPath.resolve(entry.derivedName).normalize();
+                boolean escapesOrIsNotDirect = !isDirectChild(derivedPath, entry.derivedName);
+                boolean recordedByAnother = recordedNames.contains(entry.derivedName) && !entry.recordedName.equals(entry.derivedName);
+                boolean alreadyExists = !escapesOrIsNotDirect && Files.exists(derivedPath, LinkOption.NOFOLLOW_LINKS);
+                entry.occupied = escapesOrIsNotDirect || recordedByAnother || alreadyExists;
+            }
+        }
+
+        private List<String> findUnownedFiles(List<Entry> entries) {
