    private static String descriptionFileName(String description) {
        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
        String keptWord = null;
        while (matcher.find()) {
            keptWord = matcher.group(1);
        }
        String digest = sha256(description);
        String prefix = keptWord == null ? "rule" : keptWord;
        // The longest possible kept word is 120 characters and the digest is 64 characters.
        return prefix + "-" + digest;
    }

    private static String sha256(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
            StringBuilder result = new StringBuilder(digest.length * 2);
            for (byte part : digest) {
                result.append(String.format("%02x", part & 0xff));
            }
            return result.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new AssertionError(e);
        }
    }

